package com.enfec.one.asset.workflow;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="purchase_orders") public class PurchaseOrder { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="request_id",nullable=false) private UUID requestId; @Column(name="po_number",nullable=false,unique=true,length=100) private String poNumber; @Column(name="vendor_name",nullable=false,length=200) private String vendorName; @Column(name="amount_minor") private Long amountMinor; @Column(length=10) private String currency="INR"; @Column(nullable=false,length=30) private String status="CREATED"; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; protected PurchaseOrder(){} public PurchaseOrder(UUID r,String n,String v,Long a,String c){requestId=r;poNumber=n;vendorName=v;amountMinor=a;currency=c==null?"INR":c;createdAt=OffsetDateTime.now(ZoneOffset.UTC);updatedAt=createdAt;} public void setStatus(String s){status=s;updatedAt=OffsetDateTime.now(ZoneOffset.UTC);} public UUID getId(){return id;} public UUID getRequestId(){return requestId;} public String getPoNumber(){return poNumber;} public String getVendorName(){return vendorName;} public Long getAmountMinor(){return amountMinor;} public String getCurrency(){return currency;} public String getStatus(){return status;} public OffsetDateTime getCreatedAt(){return createdAt;} }
